std::size_t Utf8SequenceLen(const std::string& s, std::size_t i) {
    const std::size_t n = s.size();
    const unsigned char c0 = static_cast<unsigned char>(s[i]);

    if (c0 < 0x80) {
        return 1;                                   // ASCII
    }
    if (c0 < 0xC2) {
        return 0;                                   // continuation byte, or overlong C0/C1
    }
    std::size_t need;
    unsigned int cp;
    if (c0 < 0xE0)      { need = 1; cp = c0 & 0x1Fu; }
    else if (c0 < 0xF0) { need = 2; cp = c0 & 0x0Fu; }
    else if (c0 < 0xF5) { need = 3; cp = c0 & 0x07u; }
    else                { return 0; }               // F5..FF: beyond U+10FFFF

    if (i + need >= n) {
        return 0;                                   // truncated at end of string
    }
    for (std::size_t k = 1; k <= need; ++k) {
        const unsigned char cc = static_cast<unsigned char>(s[i + k]);
        if ((cc & 0xC0u) != 0x80u) {
            return 0;
        }
        cp = (cp << 6) | (cc & 0x3Fu);
    }
    if (need == 1 && cp < 0x80u)     { return 0; }  // overlong
    if (need == 2 && cp < 0x800u)    { return 0; }  // overlong
    if (need == 3 && cp < 0x10000u)  { return 0; }  // overlong
    if (cp > 0x10FFFFu)              { return 0; }
    if (cp >= 0xD800u && cp <= 0xDFFFu) { return 0; } // surrogate
    return need + 1;
}

std::string RepairUtf8(const std::string& s) {
    std::string out;
    out.reserve(s.size());
    std::size_t i = 0;
    while (i < s.size()) {
        const std::size_t len = Utf8SequenceLen(s, i);
        if (len == 0) {
            out.append(kReplacement, 3);
            ++i;
        } else {
            out.append(s, i, len);
            i += len;
        }
    }
    return out;
}

bool Cp950ToUtf8(const std::string& s, std::string* out) {
    const int wideLen = ::MultiByteToWideChar(
        950, MB_ERR_INVALID_CHARS, s.data(), static_cast<int>(s.size()), NULL, 0);
    if (wideLen <= 0) {
        return false;
    }
    std::wstring wide;
    wide.resize(static_cast<std::size_t>(wideLen));
    if (::MultiByteToWideChar(950, MB_ERR_INVALID_CHARS, s.data(),
                              static_cast<int>(s.size()), &wide[0], wideLen) != wideLen) {
        return false;
    }
    const int utf8Len = ::WideCharToMultiByte(
        CP_UTF8, 0, wide.data(), wideLen, NULL, 0, NULL, NULL);
    if (utf8Len <= 0) {
        return false;
    }
    std::string utf8;
    utf8.resize(static_cast<std::size_t>(utf8Len));
    if (::WideCharToMultiByte(CP_UTF8, 0, wide.data(), wideLen, &utf8[0], utf8Len,
                              NULL, NULL) != utf8Len) {
        return false;
    }
    out->swap(utf8);
    return true;
}

bool IsValidUtf8(const std::string& s) {
    std::size_t i = 0;
    while (i < s.size()) {
        const std::size_t len = Utf8SequenceLen(s, i);
        if (len == 0) {
            return false;
        }
        i += len;
    }
    return true;
}

std::string SanitizeToUtf8(const std::string& raw) {
    if (raw.empty()) {
        return raw;
    }
    // (a) already valid UTF-8 -- pass through untouched.
    if (IsValidUtf8(raw)) {
        return raw;
    }
#if defined(_WIN32)
    // (b) assume legacy Big5 / CP950 (what the V899 tree and machine config
    //     files actually contain) and transcode.
    std::string converted;
    if (Cp950ToUtf8(raw, &converted) && IsValidUtf8(converted)) {
        return converted;
    }
#endif
    // (c) last resort: byte-wise U+FFFD replacement. Never emits invalid UTF-8.
    return RepairUtf8(raw);
}

void ForceJsonDecimalPoint(std::string* text) {
    const struct lconv* lc = ::localeconv();
    if (lc == 0 || lc->decimal_point == 0) {
        return;
    }
    const char sep = lc->decimal_point[0];
    if (sep == '.' || sep == '\0') {
        return;
    }
    for (std::size_t i = 0; i < text->size(); ++i) {
        if ((*text)[i] == sep) {
            (*text)[i] = '.';
        }
    }
}

std::string JsonNumber(wb_int64 v) {
    char tmp[32];
    // No %lld under MSVC's older CRTs and no <inttypes.h> guarantee under MinGW
    // 6.3 -- format by hand, which is also locale-proof.
    bool neg = false;
    unsigned long long mag;
    if (v < 0) {
        neg = true;
        // -(min) overflows; go through unsigned.
        mag = static_cast<unsigned long long>(-(v + 1)) + 1ull;
    } else {
        mag = static_cast<unsigned long long>(v);
    }
    int pos = 31;
    tmp[pos] = '\0';
    if (mag == 0) {
        tmp[--pos] = '0';
    }
    while (mag > 0) {
        tmp[--pos] = static_cast<char>('0' + static_cast<int>(mag % 10ull));
        mag /= 10ull;
    }
    if (neg) {
        tmp[--pos] = '-';
    }
    return std::string(&tmp[pos]);
}

std::string JsonNumber(double v) {
    // NaN and +/-Inf are not representable in JSON. Emitting them makes the
    // browser throw on JSON.parse and lose the whole frame, so map to null --
    // which the web side already renders as "---" (unknown).
    if (v != v) {
        return "null";                       // NaN
    }
    // AI(W906-BA-Cyl13) 20260911: this test used to be
    //     if (v > 1.7976931348623157e308 || v < -1.7976931348623157e308)
    // i.e. "bigger than DBL_MAX spelled out in decimal, therefore infinite".
    // With x87 excess precision that is wrong: FLT_EVAL_METHOD == 2 evaluates the
    // LITERAL at 80-bit, where decimal 1.7976931348623157e308 sits just below the
    // true DBL_MAX (1.79769313486231570815e308), so DBL_MAX compares GREATER than
    // its own spelling and the largest finite reading was silently emitted as JSON
    // null -- which the web side renders as "---", i.e. a perfectly good value
    // shown as "unknown".
    //
    // ⚠ MEASURED ON BOTH TOOLCHAINS IN THIS TREE, because they disagree, and that
    // is the part worth writing down (probe: scratchpad/fltprobe2.cpp, a noinline
    // function taking `double v` by value, matching this call shape):
    //
    //                              old_test(DBL_MAX)   isinf(DBL_MAX)
    //   MinGW.org 6.3.0 (mingw32)          0                 0     agree
    //   MinGW-W64 16.2.0 (i686)            1                 0     <-- fires
    //
    // build.bat pins MinGW.org 6.3.0, so the ORACLE line never showed this. The
    // 16.2.0 toolchain does, and this tree just acquired build_x64.bat and
    // build_nonoracle.bat, which is exactly how it becomes reachable here.
    //
    // (A first probe of mine reported "does not reproduce" on both. That probe
    // declared `volatile double v`, which forces a double-precision memory
    // round-trip and destroys the excess precision being measured -- it answered
    // a different question. The instrument was the bug, not the claim.)
    //
    // Ask the classification predicate instead of inventing a threshold: isinf is
    // exact regardless of evaluation precision. Comparing against the DBL_MAX
    // macro would also work -- both sides then widen identically -- but it still
    // reads as a magnitude test for what is really a class test.
    if (std::isinf(v)) {
        return "null";                       // +/-Inf
    }

    // Shortest form that round-trips exactly. 15 digits covers essentially all
    // real temperature/position values; 16 and 17 are the exactness backstops.
    char buf[64];
    for (int prec = 15; prec <= 17; ++prec) {
        std::snprintf(buf, sizeof(buf), "%.*g", prec, v);
        std::string text(buf);
        ForceJsonDecimalPoint(&text);
        if (std::strtod(text.c_str(), 0) == v) {
            return text;
        }
    }
    std::snprintf(buf, sizeof(buf), "%.17g", v);
    std::string text(buf);
    ForceJsonDecimalPoint(&text);
    return text;
}

